import { Messenger } from "@coze/web-sdk-kit";
const COZE_SDK_URL = 'https://sdk.coze.site';
class CozeWebSDK {
    init(options) {
        const { container } = options;
        this.iframe = this.createIframe(container || 'body');
        this.messenger = this.createMessenger(this.iframe, options);
    }
    updateConfig(config) {
        if (!this.messenger) throw new Error('messenger is null, please init first');
        this.messenger?.send('UPDATE_CONFIG', config);
    }
    updateToken(token) {
        if (!this.messenger) throw new Error('messenger is null, please init first');
        this.messenger?.send('UPDATE_TOKEN', {
            token
        });
    }
    destroy() {
        this.iframe?.remove();
        this.iframe = null;
        this.messenger = null;
    }
    createIframe(container) {
        const iframe = document.createElement('iframe');
        iframe.src = COZE_SDK_URL;
        iframe.style.width = '100%';
        iframe.style.height = '100%';
        iframe.style.border = 'none';
        let parentContainer = null;
        parentContainer = 'string' == typeof container ? document.querySelector(container) : container;
        if (!parentContainer) throw new Error('container is not valid');
        parentContainer.appendChild(iframe);
        return iframe;
    }
    createMessenger(iframe, options) {
        const messenger = new Messenger({
            targetWindow: ()=>{
                if (!iframe.contentWindow) throw new Error('iframe contentWindow is null');
                return iframe.contentWindow;
            },
            targetOrigin: COZE_SDK_URL,
            selfSource: 'host'
        });
        messenger.on('IFRAME_READY', ()=>{
            this.initIframe(options);
            options.onIframeReady?.();
        });
        messenger.on('IFRAME_DESTROY', ()=>{
            options.onIframeDestroy?.();
        });
        messenger.on('PROJECT_INFO_LOADED', (payload)=>{
            options.onProjectInfoLoaded?.(payload);
        });
        messenger.on('TOKEN_EXPIRED', async ()=>{
            if ('function' == typeof options.refreshToken) {
                const token = await options.refreshToken();
                this.updateToken(token);
            } else options.onTokenExpired?.();
        });
        messenger.on('TOKEN_INVALID', ()=>{
            options.onTokenInvalid?.();
        });
        messenger.on('NETWORK_ERROR', (payload)=>{
            options.onNetworkError?.(payload);
        });
        messenger.on('NOTIFY', (payload)=>{
            options.onNotify?.(payload);
        });
        return messenger;
    }
    async initIframe(options) {
        if (!this.messenger) throw new Error('messenger is null');
        const { token, refreshToken, projectId, theme, unauthorizedDescription } = options;
        let currentToken = token;
        if (!currentToken && 'function' == typeof refreshToken) currentToken = await refreshToken();
        this.messenger.send('INIT', {
            projectId,
            token: currentToken,
            theme,
            unauthorizedDescription
        });
    }
    constructor(){
        this.iframe = null;
        this.messenger = null;
    }
}
const cozeWebSDK = new CozeWebSDK();
export { CozeWebSDK, cozeWebSDK };
